<script setup>import { computed } from 'vue'; import { mockAnalysis } from '../data/mockAnalysis'; const props = defineProps({ selectedText: String, result: Object }); const analysis = computed(() => props.result || mockAnalysis.knowledge)</script><template><section class="analysis"><h3>知识背景</h3><label>当前探索</label><blockquote>{{ selectedText || '选中古文中的一句话，探索它背后的知识。' }}</blockquote><p>{{ analysis.summary || analysis.content }}</p><small v-if="analysis.keywords?.length">关键词：{{ analysis.keywords.join(' · ') }}</small></section></template>
